const companies = $input.all();
const output = [];

function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function absoluteUrl(href, base) {
  try { return new URL(href, base).href; } catch { return null; }
}

function looksLikeJobTitle(text) {
  return text && text.length >= 2 && text.length <= 200;
}

for (const item of companies) {
  const company = item.json || {};
  const companyId = company.id;
  const sourceUrl = company.career_page_url;

  if (!companyId || !sourceUrl) {
    output.push({ json: { company_id: companyId || null, source_url: sourceUrl || null, job_url: null, title: null, is_valid: false, status: 'missing_company_id_or_url' } });
    continue;
  }

  let html;
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: sourceUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36' },
      returnFullResponse: false
    });
    html = typeof response === 'string' ? response : (response.data ?? response.body ?? response.html ?? JSON.stringify(response));
  } catch (error) {
    output.push({ json: { company_id: companyId, source_url: sourceUrl, job_url: null, title: null, is_valid: false, status: 'career_page_fetch_failed', reason: error.message } });
    continue;
  }

  const found = new Map();

  // 1. JSON-LD
  for (const m of html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const entries = [].concat(JSON.parse(m[1].trim()));
      for (const entry of entries) {
        for (const obj of (entry?.['@graph'] || [entry])) {
          if (obj?.['@type'] !== 'JobPosting') continue;
          const title = cleanText(obj.title);
          const url = absoluteUrl(obj.url || obj['@id'], sourceUrl);
          if (title && url) found.set(url, { company_id: companyId, source_url: sourceUrl, job_url: url, title, is_valid: true, status: 'job_discovered', discovery_method: 'json-ld' });
        }
      }
    } catch {}
  }

  // 2. Targeted jobTitle-link anchors (SuccessFactors) - href first
  for (const m of html.matchAll(/<a[^>]+href="([^"]+)"[^>]*class="[^"]*jobTitle-link[^"]*"[^>]*>([^<]+)<\/a>/gi)) {
    const url = absoluteUrl(m[1], sourceUrl);
    const title = cleanText(m[2]);
    if (url && looksLikeJobTitle(title) && !found.has(url))
      found.set(url, { company_id: companyId, source_url: sourceUrl, job_url: url, title, is_valid: true, status: 'job_discovered', discovery_method: 'targeted-anchor' });
  }

  // 2b. Targeted jobTitle-link anchors - class first
  for (const m of html.matchAll(/<a[^>]+class="[^"]*jobTitle-link[^"]*"[^>]+href="([^"]+)"[^>]*>([^<]+)<\/a>/gi)) {
    const url = absoluteUrl(m[1], sourceUrl);
    const title = cleanText(m[2]);
    if (url && looksLikeJobTitle(title) && !found.has(url))
      found.set(url, { company_id: companyId, source_url: sourceUrl, job_url: url, title, is_valid: true, status: 'job_discovered', discovery_method: 'targeted-anchor' });
  }

  // 3. Generic /job/ anchor fallback
  for (const m of html.matchAll(/<a\b[^>]+href="(\/job\/[^"]+)"[^>]*>([^<]{2,200})<\/a>/gi)) {
    const url = absoluteUrl(m[1], sourceUrl);
    const title = cleanText(m[2]);
    if (url && looksLikeJobTitle(title) && !found.has(url))
      found.set(url, { company_id: companyId, source_url: sourceUrl, job_url: url, title, is_valid: true, status: 'job_discovered', discovery_method: 'generic-anchor' });
  }

  if (found.size === 0) {
    output.push({ json: { company_id: companyId, source_url: sourceUrl, job_url: null, title: null, is_valid: false, status: 'no_jobs_found', html_length: html.length } });
    continue;
  }

  for (const job of found.values()) output.push({ json: job });
}

return output;

const item = $input.item.json;
const jobUrl = item.job_url;

if (!jobUrl) {
  return [{ json: { ...item, is_valid: false, status: 'missing_job_url', reason: 'No individual job URL was discovered' } }];
}

let html;
try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: jobUrl,
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36' },
    returnFullResponse: false
  });
  html = typeof response === 'string' ? response : (response.data ?? response.body ?? response.html ?? JSON.stringify(response));
} catch (error) {
  return [{ json: { ...item, is_valid: false, status: 'job_detail_fetch_failed', reason: error.message } }];
}

if (!html || html.length < 100) {
  return [{ json: { ...item, is_valid: false, status: 'empty_job_detail', reason: 'Job detail page returned empty or very small response' } }];
}

return [{ json: { ...item, html, is_valid: true, status: 'job_detail_fetched' } }];

const item = $input.item.json;
const html = item.html || '';

function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function firstMatch(patterns, text = html) {
  for (const pattern of patterns) {
    const match = pattern.exec(text);
    if (match && match[1]) {
      const value = cleanText(match[1]);
      if (value) return value;
    }
  }
  return null;
}

function parseJsonLdJobPosting() {
  const regex = /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let match;
  while ((match = regex.exec(html)) !== null) {
    try {
      const data = JSON.parse(match[1].trim());
      const candidates = [];
      function collect(obj) {
        if (!obj || typeof obj !== 'object') return;
        if (Array.isArray(obj)) { for (const e of obj) collect(e); return; }
        const type = obj['@type'] || obj.type;
        if (type === 'JobPosting' || (Array.isArray(type) && type.includes('JobPosting'))) candidates.push(obj);
        if (Array.isArray(obj['@graph'])) for (const e of obj['@graph']) collect(e);
      }
      collect(data);
      if (candidates.length > 0) return candidates[0];
    } catch {}
  }
  return null;
}

function locationFromJsonLd(job) {
  if (!job?.jobLocation) return null;
  const locations = Array.isArray(job.jobLocation) ? job.jobLocation : [job.jobLocation];
  return locations.map(loc => {
    if (typeof loc === 'string') return loc;
    const a = loc.address || {};
    return [a.streetAddress, a.addressLocality, a.addressRegion, a.postalCode, a.addressCountry].filter(Boolean).join(', ');
  }).filter(Boolean).join(' | ') || null;
}

function salaryFromJsonLd(job) {
  const salary = job?.baseSalary || null;
  if (!salary || typeof salary !== 'object') return {};
  const value = salary.value && typeof salary.value === 'object' ? salary.value : salary;
  return {
    salary_min: value.minValue != null ? Number(value.minValue) : value.value != null ? Number(value.value) : null,
    salary_max: value.maxValue != null ? Number(value.maxValue) : value.value != null ? Number(value.value) : null,
    currency: salary.currency || value.currency || null
  };
}

const jsonLd = parseJsonLdJobPosting();
let title = cleanText(jsonLd?.title) || cleanText(item.title) || null;
let description = jsonLd?.description ? cleanText(jsonLd.description) : null;
let location = locationFromJsonLd(jsonLd);
let jobType = jsonLd?.employmentType || null;
let postedAt = jsonLd?.datePosted || null;
let expiresAt = jsonLd?.validThrough || null;
let applicationUrl = jsonLd?.url || null;
const salary = salaryFromJsonLd(jsonLd);

if (!title) title = firstMatch([/<h1\b[^>]*>([\s\S]*?)<\/h1>/i, /<title\b[^>]*>([\s\S]*?)<\/title>/i]);

if (!description) {
  description = firstMatch([
    /<(?:div|section|article)\b[^>]*(?:class|id)=["'][^"']*(?:jobDescriptionContent|job-description|job_description|jobDescription|description|job-details|job-details-content|job-content)[^"']*["'][^>]*>([\s\S]*?)<\/(?:div|section|article)>/i,
    /<(?:div|section|article)\b[^>]*(?:class|id)=["'][^"']*(?:description|responsibilities|qualifications|requirements)[^"']*["'][^>]*>([\s\S]*?)<\/(?:div|section|article)>/i,
    /<main\b[^>]*>([\s\S]*?)<\/main>/i,
    /<article\b[^>]*>([\s\S]*?)<\/article>/i
  ]);
}

function extractSection(headingPattern) {
  const regex = new RegExp('<(?:h2|h3|h4|strong|b)[^>]*>\\s*([^<]*' + headingPattern + '[^<]*)\\s*<\\/(?:h2|h3|h4|strong|b)>[\\s\\S]{0,3000}?((?:<ul[\\s\\S]*?<\\/ul>)|(?:<ol[\\s\\S]*?<\\/ol>)|(?:<p[\\s\\S]*?<\\/p>))', 'i');
  const match = regex.exec(html);
  if (!match) return [];
  const content = match[2];
  const bullets = [];
  for (const bm of content.matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)) {
    const text = cleanText(bm[1]);
    if (text) bullets.push(text);
  }
  if (bullets.length > 0) return bullets;
  const text = cleanText(content);
  return text ? [text] : [];
}

const requirements = extractSection('requirements?|qualifications?|what we[\\s\\S]{0,10}looking for|what you[\\s\\S]{0,10}need|must have|essential skills');
const niceToHave = extractSection('preferred qualifications?|preferred skills?|nice to have|bonus|good to have|plus|desirable');

if (!location) location = firstMatch([/<(?:span|div|p)\b[^>]*(?:class|id)=["'][^"']*(?:jobLocation|job-location|location)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|p)>/i]);
if (!jobType) jobType = firstMatch([/<(?:span|div|p)\b[^>]*(?:class|id)=["'][^"']*(?:employmentType|employment-type|jobType|job-type)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|p)>/i]);
if (!postedAt) postedAt = firstMatch([/<(?:span|div|time)\b[^>]*(?:class|id)=["'][^"']*(?:posted|datePosted|job-date|posted-date)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|time)>/i]);

if (!applicationUrl) {
  const applyMatch = /<a\b[^>]*href=["']([^"']+)["'][^>]*>[\s\S]{0,150}?(?:apply now|apply for this job|apply)[\s\S]{0,150}?<\/a>/i.exec(html);
  if (applyMatch) { try { applicationUrl = new URL(applyMatch[1], item.job_url).href; } catch { applicationUrl = null; } }
}
if (applicationUrl) { try { applicationUrl = new URL(applicationUrl, item.job_url).href; } catch { applicationUrl = null; } }

if (!description || description.length < 30) {
  return [{ json: { ...item, html: undefined, is_valid: false, status: 'job_details_incomplete', reason: 'Could not extract a meaningful job description' } }];
}
if (!title || title.length < 3) {
  return [{ json: { ...item, html: undefined, is_valid: false, status: 'job_details_incomplete', reason: 'Could not extract a meaningful job title' } }];
}

const remoteText = [location || '', description || ''].join(' ').toLowerCase();
let remoteType = null;
if (/\bfully remote\b|\bremote position\b|\bwork remotely\b|\b100% remote\b/.test(remoteText)) remoteType = 'remote';
else if (/\bhybrid\b/.test(remoteText)) remoteType = 'hybrid';
else if (/\bon[- ]site\b|\bonsite\b|\bin office\b/.test(remoteText)) remoteType = 'on-site';

return [{ json: {
  company_id: item.company_id,
  source_url: item.source_url,
  job_url: item.job_url,
  title: title.trim(),
  description: description.substring(0, 20000).trim(),
  location: location || null,
  job_type: jobType || null,
  remote_type: remoteType,
  salary_min: salary.salary_min ?? null,
  salary_max: salary.salary_max ?? null,
  currency: salary.currency || null,
  experience_required: null,
  experience_level: null,
  requirements,
  nice_to_have: niceToHave,
  application_url: applicationUrl || item.job_url,
  posted_at: postedAt || null,
  expires_at: expiresAt || null,
  is_valid: true,
  metadata: { extraction: { strategy: 'json-ld-then-regex', detail_page_fetched: true, json_ld_found: Boolean(jsonLd) } }
} }];
